:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-stone-wash: #f4f4f2;
  --color-frosted-wash: #eceff6;
  --color-dove-pill: #efefec;
  --color-pebble-fill: #ebebe8;
  --color-ink: #0d0d0d;
  --color-charcoal-heading: #2b2b29;
  --color-slate-ink: #2b3040;
  --color-graphite-caption: #5b5b58;
  --color-ash-muted: #8e8e8a;
  --color-fog-border: #e9e9e6;
  --color-cobalt-agent: #4a52d8;
  --color-signal-blue: #3b5bff;

  /* Typography — Font Families */
  --font-geist: "Geist", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 10.5px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: 0.72px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.55;
  --tracking-body: -0.07px;
  --text-body-lg: 15px;
  --leading-body-lg: 1.55;
  --tracking-body-lg: -0.075px;
  --text-subheading: 19px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0px;
  --text-heading-sm: 19px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: -0.285px;
  --text-heading: 36px;
  --leading-heading: 1.1;
  --tracking-heading: -1.44px;
  --text-display: 56px;
  --leading-display: 1.02;
  --tracking-display: -2.24px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-22: 22px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-168: 168px;

  /* Layout */
  --layout-max-width: 1264px;
  --layout-section-gap: 168px;
  --layout-card-padding: 20px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-sm-2: 6px;
  --radius-md: 10px;
  --radius-lg: 12px;
  --radius-lg-2: 14px;
  --radius-xl: 18px;
  --radius-xl-2: 20px;
  --radius-2xl: 22px;
  --radius-3xl: 24px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 999px;
  --radius-nav: 999px;
  --radius-tags: 999px;
  --radius-badges: 9999px;
  --radius-sections: 22px;
  --radius-images: 20px;
  --radius-cards: 18px;
  --radius-small-cards: 14px;
  --radius-inner-tiles: 12px;
  --radius-small-elements: 4px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.05) 0px 1px 2px 0px;
  --shadow-subtle-2: rgba(17, 17, 19, 0.07) 0px 0px 0px 1px inset, rgba(255, 255, 255, 0.3) 0px 1px 1.5px 0px inset;
  --shadow-sm: rgba(0, 0, 0, 0.02) 0px 3px 6px -2px, rgba(0, 0, 0, 0.04) 0px 1px 1px 0px;
  --shadow-sm-2: rgba(0, 0, 0, 0.05) 0px 1px 2px 0px, rgba(0, 0, 0, 0.035) 0px 1px 1px 0px;
  --shadow-md: rgba(0, 0, 0, 0.03) 0px 10px 15px -3px, rgba(0, 0, 0, 0.03) 0px 4px 6px -4px;
  --shadow-md-2: rgba(0, 0, 0, 0.06) 0px 1px 2px 0px, rgba(0, 0, 0, 0.12) 0px 4px 10px -4px, rgba(255, 255, 255, 0.9) 0px 1px 0px 0px inset;
  --shadow-lg: rgba(13, 13, 13, 0.06) 0px 0px 0px 1px, rgba(0, 0, 0, 0.04) 0px 1px 2px 0px, rgba(20, 24, 60, 0.18) 0px 24px 60px -32px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-stone-wash: #f4f4f2;
  --surface-frosted-wash: #eceff6;
  --surface-ink: #0d0d0d;
}

